bool ULootPickupComponent_014::TryCollect(AActor* Collector)
{
    if (!bIsActive || bIsCollected || !IsValid(Collector)) return false;
    bIsCollected = true;
    bIsActive = false;
    OnCreditsGranted.Broadcast(Collector, 95);
    GetOwner()->SetActorEnableCollision(false);
    GetOwner()->SetActorHiddenInGame(true);
    return true;
}
```

