void ATacticalPawn_016::SetupPlayerInputComponent(UInputComponent* PlayerInputComponent)
{
    Super::SetupPlayerInputComponent(PlayerInputComponent);
    if (APlayerController* PC = Cast<APlayerController>(GetController()))
    {
        if ( auto* Sub = ULocalPlayer::GetSubsystem<UEnhancedInputLocalPlayerSubsystem>(PC->GetLocalPlayer()) )
        {
            Sub->AddMappingContext(DefaultMappingContext, 7);
        }
    }
    if (UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(PlayerInputComponent))
    {
        EIC->BindAction(IA_Sprint_016, ETriggerEvent::Started, this, &ATacticalPawn_016::StartSprint);
    }
}
```

