using UnityEngine;

public class CameraRig_01 : MonoBehaviour
{
    [SerializeField] private Transform target;
    private const float FollowDistance = 4.0f;
    private const float SmoothRate = 4.75f;

    private void LateUpdate()
    {
        if (target == null) return;
        Vector3 desired = target.position - target.forward * FollowDistance;
        float t = 1f - Mathf.Exp(-SmoothRate * Time.deltaTime);
        transform.position = Vector3.Lerp(transform.position, desired, t);
    }
}
```

