using UnityEngine;

[RequireComponent(typeof(Rigidbody))]
public class RigidbodyMover_009 : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 6.8f;
    private Rigidbody _rb;
    private Vector3 _cachedInput;

    private void Awake() => _rb = GetComponent<Rigidbody>();
    private void Update() => _cachedInput = new Vector3(Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical")).normalized;
    private void FixedUpdate() => _rb.MovePosition(_rb.position + _cachedInput * (moveSpeed * Time.fixedDeltaTime));
}
