using Unity.Burst;
using Unity.Entities;
using Unity.Mathematics;
using Unity.Transforms;

[BurstCompile]
public partial struct ProjectileSimSystem_010 : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        float dt = SystemAPI.Time.DeltaTime;
        foreach (var (xform, vel) in SystemAPI.Query<RefRW<LocalTransform>, RefRO<LinearVelocity>>())
        {
            float3 v = math.normalizesafe(vel.ValueRO.Value) * math.min(math.length(vel.ValueRO.Value), 35.0f);
            xform.ValueRW.Position += v * dt;
        }
    }
}
